const LANGUAGE_LABELS = { cpp: 'C++', java: 'Java', csharp: 'C#', javascript: 'JavaScript (Node.js)', python: 'Python', sql: 'SQL (SQLite)', html: 'HTML preview', css: 'CSS preview' };
function lesson(course, moduleId, index, spec) {
  const [title, objective, material, example, practice, deliverable, code = false] = spec;
  const id = `${course.id}-l${String(index + 1).padStart(2, '0')}`;
  const row = {
    id, title, minutes: 25 + ((index * 7 + course.id.length) % 26), objective, material, example,
    practice, deliverable, moduleId,
    sections: [
      { id: `${id}-theory`, type: 'theory', title: 'Lý thuyết cốt lõi', content: material },
      { id: `${id}-example`, type: 'worked-example', title: 'Ví dụ minh họa', content: example },
      { id: `${id}-practice`, type: 'practice', title: 'Thực hành có hướng dẫn', content: practice },
      { id: `${id}-reflection`, type: 'reflection', title: 'Tự đánh giá', content: `Kiểm tra sản phẩm “${deliverable}” theo mục tiêu bài. Nêu một điều đã đúng, một lỗi/giới hạn và bước cải thiện tiếp theo.` }
    ],
    videoUrl: '', videoStatus: 'placeholder-to-be-replaced', contentStatus: 'draft-teacher-review-required'
  };
  if (code && course.languages?.length) {
    row.codeExercise = {
      enabled: true, instructions: practice,
      languages: course.languages,
      runnableLanguages: course.languages.filter((item) => ['cpp', 'java', 'csharp', 'javascript', 'python', 'sql'].includes(item)),
      defaultLanguage: course.defaultLanguage || course.languages.find((item) => ['cpp', 'java', 'csharp', 'javascript', 'python', 'sql'].includes(item)) || course.languages[0],
      starterCodeByLanguage: Object.fromEntries(course.languages.map((language) => [language, starterFor(language, title, practice)])),
      sampleStdin: '',
      note: 'Mã chạy qua sandbox trình thực thi. HTML/CSS chỉ xem trước trong iframe được sandbox ở trình duyệt.'
    };
  }
  return row;
}
function buildModule(course, index, spec, startIndex) {
  const [title, summary, lessonSpecs] = spec;
  const id = `${course.id}-m${index + 1}`;
  return { id, title, summary, lessons: lessonSpecs.map((item, offset) => lesson(course, id, startIndex + offset, item)) };
}
function makeCourse(group, spec) {
  const course = { ...spec, groupId: group.id, groupCode: group.code, groupTitle: group.title };
  const modules = spec.modules.map((unit, index) => buildModule(course, index, unit, index * 3));
  const lessons = modules.flatMap((item) => item.lessons);
  return { ...course, modules, lessons, lessonCount: lessons.length, moduleCount: modules.length, questionBankTarget: lessons.length * 48, contentStatus: 'draft-teacher-review-required' };
}
function mkLesson(title, objective, material, example, practice, deliverable, code = true) { return [title, objective, material, example, practice, deliverable, code]; }
function mkModule(title, summary, lessons) { return [title, summary, lessons]; }

