const GROUPS = DEFINITIONS.map((definition) => {
  const group = { id: definition.id, code: definition.code, number: definition.number, title: definition.title, englishTitle: definition.englishTitle, description: definition.description, careers: definition.careers, contentStatus: 'draft-teacher-review-required' };
  const COURSES = definition.courses.map((course) => makeCourse(group, course));
  const validCourses = new Set(COURSES.map((course) => course.id));
  const PATHWAYS = definition.pathways.map((pathway) => ({ ...pathway, courseIds: pathway.courseIds.filter((courseId) => validCourses.has(courseId)) }));
  group.pathways = PATHWAYS;
  group.subjectCodes = COURSES.map((course) => course.code);
  group.courseCount = COURSES.length;
  group.lessonCount = COURSES.reduce((sum, course) => sum + course.lessonCount, 0);
  return { GROUP: group, PATHWAYS, COURSES };
});

function listGroups() {
  return GROUPS.map(({ GROUP, PATHWAYS, COURSES }) => ({ ...GROUP, pathways: PATHWAYS, courseCount: COURSES.length, lessonCount: COURSES.reduce((sum, item) => sum + item.lessonCount, 0) }));
}
function listCourses(groupId) {
  return GROUPS.filter((item) => !groupId || item.GROUP.id === groupId || item.GROUP.code === groupId || String(item.GROUP.number) === String(groupId))
    .flatMap(({ GROUP, COURSES }) => COURSES.map(({ modules, lessons, ...summary }) => ({ ...summary, moduleCount: modules.length, lessonCount: lessons.length, groupId: GROUP.id, groupCode: GROUP.code, groupTitle: GROUP.title })));
}
function getGroup(groupId) { return GROUPS.find((item) => item.GROUP.id === groupId || item.GROUP.code === groupId || String(item.GROUP.number) === String(groupId)) || null; }
function getCourse(courseId) { for (const item of GROUPS) { const found = item.COURSES.find((course) => course.id === courseId || course.code === courseId); if (found) return found; } return null; }
function getAllCourses() { return GROUPS.flatMap((item) => item.COURSES); }
function publicCourseDetail(course) {
  if (!course) return null;
  const { modules, lessons, ...summary } = course;
  const publicModules = modules.map((unit) => ({ ...unit, lessons: unit.lessons.map((item) => ({ ...item, codeExercise: item.codeExercise ? { ...item.codeExercise, starterCodeByLanguage: item.codeExercise.starterCodeByLanguage, note: item.codeExercise.note } : undefined })) }));
  return { ...summary, modules: publicModules, lessons: publicModules.flatMap((unit) => unit.lessons) };
}
module.exports = { GROUPS, listGroups, listCourses, getGroup, getCourse, getAllCourses, publicCourseDetail, LANGUAGE_LABELS, starterFor };
